import{_ as e,o as n,c as s,a0 as l}from"./chunks/framework.Bogozrur.js";const u=JSON.parse('{"title":"2026-07-03：用 AI 重新整理计算机基础学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-07-03-cs-learning-path.md","filePath":"blog/2026-07-03-cs-learning-path.md"}'),p={name:"blog/2026-07-03-cs-learning-path.md"};function t(i,a,o,r,c,h){return n(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="_2026-07-03-用-ai-重新整理计算机基础学习路径" tabindex="-1">2026-07-03：用 AI 重新整理计算机基础学习路径 <a class="header-anchor" href="#_2026-07-03-用-ai-重新整理计算机基础学习路径" aria-label="Permalink to &quot;2026-07-03：用 AI 重新整理计算机基础学习路径&quot;">​</a></h1><p>今天借助 AI 重新整理了 <code>计算机基础</code> 这个资料包，把原来分散的数学、C++、算法、系统、Python/AI 和自然科学支线放进同一条长期学习路径里。</p><p>这次整理最重要的变化，不是又多收集了一批资料，而是把“先学什么、学到什么程度、什么时候进入下一阶段”写清楚了。</p><h2 id="从资料堆到学习系统" tabindex="-1">从资料堆到学习系统 <a class="header-anchor" href="#从资料堆到学习系统" aria-label="Permalink to &quot;从资料堆到学习系统&quot;">​</a></h2><p>之前看计算机基础相关内容，很容易被资料数量拖着走：这里有一门 MIT 课，那里有一个 GitHub 项目，再加上数学、系统、AI、电子方向，每一块都看起来重要。</p><p>今天整理后的资料包更像一个学习系统。顶层先看 <code>学习顺序和路径.md</code>、<code>外部学习路径对比与优化.md</code> 和 <code>混合课程体系说明.md</code>，再进入各个子模块。</p><p>目前目录被拆成几条清楚的线：</p><ul><li><code>数学/</code>：离散数学、高等代数、概率统计、数学分析</li><li><code>C++学习资料包/</code>：C++ 语言、算法与数据结构、项目、MIT 课程和开源项目实战</li><li><code>计算机系统/</code>：系统基础、操作系统、网络、数据库、编译原理</li><li><code>Python与AI基础/</code>：Python、科学计算、PyTorch、深度学习项目</li><li><code>自然科学与电子基础/</code>：物理、DSP、电路、电子和硬件相关支线</li></ul><p>这样看下来，路径不再是“今天想学什么就点什么”，而是有主线、有支线、有验收。</p><h2 id="重新确定的主线" tabindex="-1">重新确定的主线 <a class="header-anchor" href="#重新确定的主线" aria-label="Permalink to &quot;重新确定的主线&quot;">​</a></h2><p>整理后的总路线大致是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C++ 基础 + 离散数学</span></span>
<span class="line"><span>  -&gt; 计算机科学与技术导论</span></span>
<span class="line"><span>  -&gt; Python 基础作为工具层</span></span>
<span class="line"><span>  -&gt; 数据结构与算法 + MIT 6.006</span></span>
<span class="line"><span>  -&gt; 高等代数 + 图/矩阵项目</span></span>
<span class="line"><span>  -&gt; 概率统计 + 随机算法/benchmark</span></span>
<span class="line"><span>  -&gt; 数学分析 + 数值计算</span></span>
<span class="line"><span>  -&gt; 科学计算 + PyTorch 基础</span></span>
<span class="line"><span>  -&gt; MIT 6.046J 算法设计与证明</span></span>
<span class="line"><span>  -&gt; MIT 6.172 + C++ 性能工程</span></span>
<span class="line"><span>  -&gt; Linux + 计算机系统基础 + 操作系统</span></span>
<span class="line"><span>  -&gt; 网络、数据库、编译原理和综合项目</span></span></code></pre></div><p>这条线对我最有用的一点是：它没有把 AI、系统、算法、数学硬塞到同一个时间段里，而是按依赖关系慢慢展开。</p><p>C++ 和离散数学先启动，算法和数据结构接上；高等代数、概率统计、数学分析用项目带进去；Python 先作为工具，PyTorch 不提前抢跑；系统课放在 C++、算法和部分数学基础之后。</p><h2 id="今天整理出的几个原则" tabindex="-1">今天整理出的几个原则 <a class="header-anchor" href="#今天整理出的几个原则" aria-label="Permalink to &quot;今天整理出的几个原则&quot;">​</a></h2><h3 id="主线少一点" tabindex="-1">主线少一点 <a class="header-anchor" href="#主线少一点" aria-label="Permalink to &quot;主线少一点&quot;">​</a></h3><p>每门课只保留一条主线，MIT、Stanford、CMU、Berkeley 这些课程不并行堆满。</p><p>MIT 用来校准深度和作业标准，其他课程只在需要另一种讲法、实验或项目时补充。这个原则能防止我把“收藏资源”误当成学习。</p><h3 id="阶段必须有闸门" tabindex="-1">阶段必须有闸门 <a class="header-anchor" href="#阶段必须有闸门" aria-label="Permalink to &quot;阶段必须有闸门&quot;">​</a></h3><p>整理后的路径给每个阶段加了可检查输出。</p><p>比如 C++ 基础阶段要留下小程序和测试；算法阶段要有算法库、复杂度分析和正确性证明；概率统计阶段要写 Monte Carlo 和 benchmark 报告；系统阶段要做 Linux、cache、进程、系统调用或等价实验。</p><p>这比“看完一门课”更硬一点，也更适合长期复盘。</p><h3 id="工具层提前" tabindex="-1">工具层提前 <a class="header-anchor" href="#工具层提前" aria-label="Permalink to &quot;工具层提前&quot;">​</a></h3><p>Git/GitHub、Linux shell、CMake、测试、Markdown、benchmark 这些工具不能等到后面再补。</p><p>今天重新看路径时意识到，工具不是附属技能。它们会影响学习记录、代码质量、项目复现和错误定位。前 1-2 个阶段就要持续使用。</p><h3 id="每隔一段时间要闭环" tabindex="-1">每隔一段时间要闭环 <a class="header-anchor" href="#每隔一段时间要闭环" aria-label="Permalink to &quot;每隔一段时间要闭环&quot;">​</a></h3><p>资料包里设定了每 8-12 周至少完成一个闭环输出：代码项目、证明题、实验报告、benchmark 报告、源码阅读笔记或跨课程小项目。</p><p>这个节奏比较现实。长期学习最怕只输入不输出，最后留下的只有浏览记录。</p><h2 id="对我自己的提醒" tabindex="-1">对我自己的提醒 <a class="header-anchor" href="#对我自己的提醒" aria-label="Permalink to &quot;对我自己的提醒&quot;">​</a></h2><p>这次整理让我更清楚一件事：计算机基础不能靠冲刺补完。</p><p>如果目标是 RoboMaster、机器人、视觉、系统和 AI 能长期走下去，数学、C++、算法、系统和工程习惯都要慢慢补。AI 可以帮我整理路径、压缩资料、生成验收清单，但不能替我完成证明、代码、调试和项目复盘。</p><p>后面要少开新坑，多按阶段闸门往前推进。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>[ ] 先按 <code>学习顺序和路径.md</code> 完成阶段 0</li><li>[ ] 建学习日志、错题/错因记录和代码目录</li><li>[ ] 确认 C++ 编译器、CMake、调试器可用</li><li>[ ] 从 C++ 基础和离散数学开始推进</li><li>[ ] 每 4-6 周跑一次资料包里的验收脚本</li></ul><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>今天把计算机基础从“很多资料”整理成了“长期路线”。接下来要看的不是收藏夹，而是每个阶段能留下什么。</p>`,36)])])}const b=e(p,[["render",t]]);export{u as __pageData,b as default};
